#pragma pack(push,1)
struct Header{char magic[8];uint32_t version,candidates,cases;};
struct Row{int32_t own_money,opp_money;uint16_t changes,flags;};
#pragma pack(pop)
struct CaseHost{std::string path;int seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct CaseDev{int tape=0,seat=0;uint64_t seed=0;int family=0,protected_flag=0,own_history=0,role=0;};
struct OppDesc{int first=0,count=0;};
struct Cand{uint16_t route=0xffffu,horizon=0;uint16_t probe=0;};
struct DevicePolicyOwner4{bonsaikg4::Node4*n=nullptr;uint16_t*c=nullptr;bonsaikg4::BbDecl4*bb=nullptr;bonsaikg4::ValueRef4*v=nullptr;bonsaikg4::FeatureArgRef4*a=nullptr;bonsaikg4::Predicate4*q=nullptr;bonsaikg4::Lifecycle4*l=nullptr;bonsaikg4::Effect4*e=nullptr;~DevicePolicyOwner4(){if(n)cudaFree(n);if(c)cudaFree(c);if(bb)cudaFree(bb);if(v)cudaFree(v);if(a)cudaFree(a);if(q)cudaFree(q);if(l)cudaFree(l);if(e)cudaFree(e);}};
template<class T>static T*cp(const std::vector<T>&v){if(v.empty())return nullptr;T*d=nullptr;KAGCUDA_CHECK(cudaMalloc((void**)&d,v.size()*sizeof(T)));KAGCUDA_CHECK(cudaMemcpy(d,v.data(),v.size()*sizeof(T),cudaMemcpyHostToDevice));return d;}
static std::vector<std::string>split_tab(const std::string&s){std::vector<std::string>o;size_t p=0;for(;;){size_t q=s.find('\t',p);o.push_back(s.substr(p,q==std::string::npos?std::string::npos:q-p));if(q==std::string::npos)break;p=q+1;}return o;}
static std::vector<CaseHost>load_cases(const std::string&p){std::ifstream in(p);if(!in)throw std::runtime_error("cases");std::vector<CaseHost>o;std::string l;while(std::getline(in,l)){if(l.empty()||l[0]=='#')continue;auto z=split_tab(l);if(z.size()!=6&&z.size()!=7)throw std::runtime_error("case fields");CaseHost c;c.path=z[0];c.seat=std::stoi(z[1]);c.seed=std::stoull(z[2]);c.family=std::stoi(z[3]);c.protected_flag=std::stoi(z[4]);c.own_history=std::stoi(z[5]);if(z.size()==7)c.role=std::stoi(z[6]);o.push_back(c);}if(o.empty())throw std::runtime_error("empty cases");return o;}
static std::vector<int>csv(const std::string&s){std::vector<int>o;size_t p=0;for(;;){size_t q=s.find(',',p);auto z=s.substr(p,q==std::string::npos?std::string::npos:q-p);if(!z.empty())o.push_back(std::stoi(z));if(q==std::string::npos)break;p=q+1;}return o;}
static bonsaikg_v6::RoutePack load_legacy_pack(const std::string&path){std::ifstream in(path,std::ios::binary);if(!in)throw std::runtime_error("legacy");std::vector<uint8_t>raw((std::istreambuf_iterator<char>(in)),{});auto full=bonsaikg::sha256_bytes(raw);if(bonsaikg_v6::hash_hex(full)!=bonsaikg4_champion::LEGACY_ROUTE_PACK_SHA256)throw std::runtime_error("legacy hash");bonsaikg_v6::PackHeader h{};std::memcpy(&h,raw.data(),sizeof(h));size_t db=(size_t)h.route_count*sizeof(bonsaikg_v6::RouteDesc);bonsaikg_v6::RoutePack o;o.routes.resize(h.route_count);o.actions.resize(h.action_count);std::memcpy(o.routes.data(),raw.data()+sizeof(h),db);std::memcpy(o.actions.data(),raw.data()+sizeof(h)+db,o.actions.size()*sizeof(o.actions[0]));return o;}
struct DeviceBasePack{const bonsaikg_v6::RouteDesc*routes=nullptr;const bonsaikg_v6::PackedAction*actions=nullptr;int n=0;__device__ __forceinline__ const bonsaikg_v6::PackedAction*at(uint16_t route,int step)const{for(int i=0;i<n;++i)if(routes[i].route_id==route){int s=step;if(s<0)s=0;if(s>=routes[i].steps)s=routes[i].steps-1;return actions+routes[i].first+s;}return nullptr;}};
__device__ __forceinline__ uint16_t reconcile_feed(const int32_t*bb,int first,int count,Action&a){uint16_t n=0;for(int u=0;u<count&&u<a.n_units;++u)if(bb[first+u]&&a.units[u].op==OP_FEED){a.units[u]=UnitAction{};++n;}return n;}
__device__ __forceinline__ bool materialize(const ObservationView&ob,const DeviceBasePack&bp,const bonsaikg4_champion::CudaLegacyPack&lp,bonsaikg4_champion::CudaLegacyState&legacy,bonsaikg_v6::CudaEngineExploitState&exploit,const int32_t*bb,int feed_slot,int feed_count,int strategic_slot,uint16_t strategic_id,uint16_t forced_route,Action&out){int route=bb[1];if(strategic_slot>=0&&bb[strategic_slot])route=strategic_id==0xffffu?(uint16_t)bb[strategic_slot]:strategic_id;if(forced_route!=0xffffu)route=forced_route;const auto*p=bp.at((uint16_t)route,ob.step());if(!p)return false;bonsaikg_v6::materialize_cuda(*p,ob.farm(ob.player()).n_units(),out);bonsaikg4_champion::apply_legacy(ob,lp,legacy,out);bonsaikg_v6::apply_cuda_engine_exploits(ob,out,exploit,legacy.external_ok!=0,100);reconcile_feed(bb,feed_slot,feed_count,out);return true;}
__device__ __forceinline__ bool same_unit(const UnitAction&a,const UnitAction&b){return a.op==b.op&&a.arg==b.arg&&a.n==b.n;}__device__ __forceinline__ bool same_order(const Order&a,const Order&b){return a.op==b.op&&a.item==b.item&&a.n==b.n;}__device__ __forceinline__ bool same_action(const Action&a,const Action&b){if(a.n_units!=b.n_units||a.n_orders!=b.n_orders)return false;for(int i=0;i<a.n_units;++i)if(!same_unit(a.units[i],b.units[i]))return false;for(int i=0;i<a.n_orders;++i)if(!same_order(a.orders[i],b.orders[i]))return false;return true;}
__device__ __forceinline__ bool recovery_gate(const ObservationView&ob,const int32_t*bb,int active_slot,int mode){if(mode==0)return true;if(active_slot<0||!bb[active_slot])return false;const auto town=ob.town();const int s0=town.n_shops()>0?town.shop(0):-1;const int s1=town.n_shops()>1?town.shop(1):-1;if(mode==1)return s0==0&&s1==6;/* BAKERY,SMOOTHIE_SHOP */if(mode==2){const auto own=ob.farm(ob.player());return s0==1&&s1==1&&own.tile(1,4).kind==T_WEED;}return false;}
__global__ void kernel(Config cfg0,DeviceTables tables,bonsaikg4::PolicyView4 policy,DeviceBasePack bp,bonsaikg4_champion::CudaLegacyPack lp,const Action*opp,const OppDesc*od,const CaseDev*cases,int nc,const Cand*cands,int nk,int feed_slot,int feed_count,int strategic_slot,uint16_t strategic_id,int specialist_active_slot,int gate_mode,int32_t*bb,bonsaikg4::NodeState4*ns,bonsaikg4::RuntimeMeta4*meta,Sim*sims,Row*out){int job=blockIdx.x*blockDim.x+threadIdx.x,total=nc*nk;if(job>=total)return;int ki=job/nc,ci=job-ki*nc;const auto cand=cands[ki];const auto c=cases[ci];Config cfg=cfg0;cfg.seed=c.seed;Sim&sim=sims[job];sim.init(cfg,&tables);bonsaikg4::RuntimeView4 st{policy.n_bb?bb+(size_t)job*policy.n_bb:nullptr,policy.n_state?ns+(size_t)job*policy.n_state:nullptr,meta+job};bonsaikg4::reset_runtime(policy,st);bonsaikg4_champion::CudaLegacyState legacy{};bonsaikg_v6::CudaEngineExploitState exploit{};bonsaikg4_champion::reset_legacy(legacy);bonsaikg_v6::reset_cuda_engine_exploits(exploit);uint16_t changes=0,flags=0;while(!sim.st.done){int step=sim.st.step,os=1-c.seat;ObservationView ob=make_observation(sim,c.seat);bonsaikg4::ActionResult4 ign{};auto status=bonsaikg4::tick4(policy,st,bonsaikg4::CudaObservation4(ob),0,ign,nullptr);if(meta[job].fault||status!=bonsaikg4::SUCCESS){flags|=1;break;}bool active=ki>0&&step>=cand.probe&&step<cand.probe+(int)cand.horizon&&recovery_gate(ob,st.blackboard,specialist_active_slot,gate_mode);Action ca{};if(active){auto lc=legacy;auto ec=exploit;Action base{};if(!materialize(ob,bp,lp,lc,ec,st.blackboard,feed_slot,feed_count,strategic_slot,strategic_id,0xffffu,base)){flags|=2;break;}if(!materialize(ob,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,strategic_slot,strategic_id,cand.route,ca)){flags|=2;break;}if(!same_action(base,ca)&&changes<65535)++changes;}else if(!materialize(ob,bp,lp,legacy,exploit,st.blackboard,feed_slot,feed_count,strategic_slot,strategic_id,0xffffu,ca)){flags|=2;break;}Action oa{};auto d=od[c.tape];if(d.count){int s=step<d.count?step:d.count-1;oa=opp[d.first+s];}oa.n_units=sim.st.farms[os].n_units;if(c.seat==0)sim.step_with_unit_counts(ca,sim.st.farms[0].n_units,oa,sim.st.farms[1].n_units);else sim.step_with_unit_counts(oa,sim.st.farms[0].n_units,ca,sim.st.farms[1].n_units);}Row r{};r.own_money=(int32_t)sim.st.farms[c.seat].money;r.opp_money=(int32_t)sim.st.farms[1-c.seat].money;r.changes=changes;r.flags=flags;out[job]=r;}
static void write_out(const std::string&p,const std::vector<Row>&r,int nk,int nc){std::ofstream o(p,std::ios::binary);Header h{{'B','4','R','C','1','\0','\0','\0'},1u,(uint32_t)nk,(uint32_t)nc};o.write((char*)&h,sizeof(h));o.write((char*)r.data(),r.size()*sizeof(r[0]));}
}
int main(int argc,char**argv){try{std::string controller,routes,legacy,casesp,outp,probes_s,horizons_s,routes_s;int feed_slot=5,feed_count=13,strategic_slot=-1,strategic_id=0xffff,specialist_active_slot=-1,gate_mode=0,tpb=64;for(int i=1;i<argc;++i){std::string z=argv[i];auto need=[&](){if(i+1>=argc)throw std::runtime_error("missing "+z);return std::string(argv[++i]);};if(z=="--controller")controller=need();else if(z=="--routes")routes=need();else if(z=="--legacy-routes")legacy=need();else if(z=="--cases")casesp=need();else if(z=="--out")outp=need();else if(z=="--probes")probes_s=need();else if(z=="--horizons")horizons_s=need();else if(z=="--route-ids")routes_s=need();else if(z=="--strategic-route-slot")strategic_slot=std::stoi(need());else if(z=="--strategic-route-id")strategic_id=std::stoi(need());else if(z=="--specialist-active-slot")specialist_active_slot=std::stoi(need());else if(z=="--gate-mode")gate_mode=std::stoi(need());else if(z=="--tpb")tpb=std::stoi(need());else throw std::runtime_error("unknown "+z);}if(controller.empty()||routes.empty()||legacy.empty()||casesp.empty()||outp.empty()||probes_s.empty()||horizons_s.empty()||routes_s.empty())throw std::runtime_error("args");auto probes=csv(probes_s),horizons=csv(horizons_s),route_ids=csv(routes_s);std::vector<Cand>hcands{{0xffffu,0,0}};for(int p:probes)for(int h:horizons)for(int r:route_ids){if(p<0||p>=720||h<=0||r<0||r>65535)throw std::runtime_error("grid value");hcands.push_back({(uint16_t)r,(uint16_t)h,(uint16_t)p});}
 auto owned=bonsaikg4::load_compiled4(controller);auto hp=owned.view();DevicePolicyOwner4 po;po.n=cp(owned.nodes);po.c=cp(owned.child_refs);po.bb=cp(owned.bb);po.v=cp(owned.values);po.a=cp(owned.feature_args);po.q=cp(owned.predicates);po.l=cp(owned.lifecycles);po.e=cp(owned.effects);auto dp=hp;dp.nodes=po.n;dp.child_refs=po.c;dp.bb=po.bb;dp.values=po.v;dp.feature_args=po.a;dp.predicates=po.q;dp.lifecycles=po.l;dp.effects=po.e;auto rp=bonsaikg4_champion::load_extended_route_pack(routes),lg=load_legacy_pack(legacy);auto*dr=cp(rp.routes);auto*da=cp(rp.actions);auto*dlr=cp(lg.routes);auto*dla=cp(lg.actions);DeviceBasePack bp{dr,da,(int)rp.routes.size()};bonsaikg4_champion::CudaLegacyPack lp{dlr,dla,(int)lg.routes.size()};auto hc=load_cases(casesp);std::vector<Action>hoa;std::vector<OppDesc>hod;std::vector<CaseDev>hcd;for(const auto&c:hc){auto t=load_native_tape_json(c.path);int off=hoa.size();hoa.insert(hoa.end(),t.actions.begin(),t.actions.end());hod.push_back({off,(int)t.actions.size()});hcd.push_back({(int)hod.size()-1,c.seat,c.seed,c.family,c.protected_flag,c.own_history,c.role});}auto*doa=cp(hoa);auto*dod=cp(hod);auto*dc=cp(hcd);auto*dca=cp(hcands);size_t jobs=(size_t)hc.size()*hcands.size();int32_t*dbb=nullptr;bonsaikg4::NodeState4*dns=nullptr;bonsaikg4::RuntimeMeta4*dm=nullptr;Sim*ds=nullptr;Row*dout=nullptr;if(hp.n_bb)cudaMalloc((void**)&dbb,jobs*hp.n_bb*sizeof(int32_t));if(hp.n_state)cudaMalloc((void**)&dns,jobs*hp.n_state*sizeof(*dns));cudaMalloc((void**)&dm,jobs*sizeof(*dm));cudaMalloc((void**)&ds,jobs*sizeof(*ds));cudaMalloc((void**)&dout,jobs*sizeof(*dout));configure_device();TablesOwner tables;Config cfg;cfg.episode_steps=720;cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);cudaEventRecord(a);kernel<<<(jobs+tpb-1)/tpb,tpb>>>(cfg,tables.dev,dp,bp,lp,doa,dod,dc,hc.size(),dca,hcands.size(),feed_slot,feed_count,strategic_slot,(uint16_t)strategic_id,specialist_active_slot,gate_mode,dbb,dns,dm,ds,dout);KAGCUDA_CHECK(cudaGetLastError());cudaEventRecord(b);cudaEventSynchronize(b);float ms=0;cudaEventElapsedTime(&ms,a,b);std::vector<Row>hr(jobs);cudaMemcpy(hr.data(),dout,jobs*sizeof(Row),cudaMemcpyDeviceToHost);int bad=0;for(auto&r:hr)bad+=r.flags!=0;write_out(outp,hr,hcands.size(),hc.size());std::cout<<"candidates="<<hcands.size()<<" cases="<<hc.size()<<" games="<<jobs<<" gpu_ms="<<ms<<" games_s="<<(jobs/(ms/1000.0))<<" bad="<<bad<<"\n";return bad?1:0;}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<'\n';return 2;}}
